# Root-owned native scheduling entry. Rechecks staged preflight & exact source-control receipt pins.
[CmdletBinding()]
param(
  [Parameter(Mandatory)][string]$StageRoot,
  [Parameter(Mandatory)][string]$PlanPath,
  [Parameter(Mandatory)][ValidatePattern('^[0-9a-fA-F]{64}$')][string]$ExpectedPlanSha256,
  [Parameter(Mandatory)][string]$PreflightPath,
  [Parameter(Mandatory)][ValidatePattern('^[0-9a-fA-F]{64}$')][string]$ExpectedPreflightSha256,
  [Parameter(Mandatory)][string]$ControlsReceiptPath,
  [Parameter(Mandatory)][ValidatePattern('^[0-9a-fA-F]{64}$')][string]$ExpectedControlsReceiptSha256,
  [Parameter(Mandatory)][string]$ScheduleReceiptPath,
  [Parameter(Mandatory)][ValidateRange(1,2000)][int]$Rows,
  [Parameter(Mandatory)][ValidateRange(0.1,1000)][double]$KeyRate
)
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
function Require([bool]$ok,[string]$message){if(-not $ok){throw $message}}
function Full([string]$path){return [IO.Path]::GetFullPath($path)}
function Hash([string]$path){return (Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLowerInvariant()}
function Read-BoundedJson([string]$path){$item=Get-Item -LiteralPath $path -Force;Require (($item.Attributes -band [IO.FileAttributes]::ReparsePoint)-eq 0 -and $item.Length -le 2097152) "bounded JSON rejected: $path";return [IO.File]::ReadAllText($item.FullName)|ConvertFrom-Json}
function Write-FreshJson([string]$path,[object]$value){$full=Full $path;Require (-not(Test-Path -LiteralPath $full)) "receipt must be fresh: $full";$parent=Split-Path -Parent $full;if(-not(Test-Path -LiteralPath $parent -PathType Container)){[IO.Directory]::CreateDirectory($parent)|Out-Null};$tmp="$full.$([guid]::NewGuid().ToString('N')).tmp";$bytes=[Text.Encoding]::UTF8.GetBytes(($value|ConvertTo-Json -Depth 12)+"`r`n");$stream=[IO.File]::Open($tmp,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read);try{$stream.Write($bytes,0,$bytes.Length);$stream.Flush($true)}finally{$stream.Dispose()};[IO.File]::Move($tmp,$full)}
$stage=Full $StageRoot;$planFile=Full $PlanPath;$preflight=Full $PreflightPath;$controls=Full $ControlsReceiptPath;$scheduleReceipt=Full $ScheduleReceiptPath
Require (Test-Path -LiteralPath $stage -PathType Container) "stage missing: $stage";Require (Test-Path -LiteralPath $planFile -PathType Leaf) "plan missing: $planFile";Require ($planFile -ceq (Full (Join-Path $stage 'one-run-plan-r8.json'))) 'native plan must be staged one-run-plan-r8.json';Require (Test-Path -LiteralPath $preflight -PathType Leaf) 'production preflight missing';Require ([IO.Path]::GetFileName($preflight) -ceq 'entry-native-r8.ps1') 'production preflight filename mismatch';Require ((Hash $preflight) -ceq $ExpectedPreflightSha256.ToLowerInvariant()) 'exact production preflight SHA-256 mismatch';$plan=Read-BoundedJson $planFile;$pins=Read-BoundedJson (Join-Path $stage 'source-pins-r8.json');$planSha=Hash $planFile;Require ($planSha -ceq $ExpectedPlanSha256.ToLowerInvariant()) 'exact plan SHA-256 mismatch';Require ([string]$pins.sourcePlanSha256 -ceq $planSha) 'source pin plan SHA-256 mismatch';Require ([string]$plan.schema -eq 'sr0-display-selfjob-v4-fresh-one-run-r8') 'plan schema mismatch';Require ([bool]$plan.noActivate -and [bool]$plan.noResources) 'interaction guards missing';Require ([int64]$plan.aggregateJobMemoryLimitBytes -eq 1073741824) '1GiB aggregate limit missing';Require ([int]$plan.deadlineSeconds -eq 900 -and [int]$plan.pollSeconds -eq 1) 'native bounds mismatch';Require ($Rows -eq 200 -and $KeyRate -eq 10) 'explicit Rows=200/KeyRate=10 required';Require (-not [bool]$plan.qualificationClaim -and [int]$plan.nativeActions -eq 0) 'native gate requires diagnostic plan'
$preflightText=& $preflight -StageRoot $stage | Out-String;$preflightSucceeded=$?;Require $preflightSucceeded 'staged production preflight failed';$preflightReceipt=$preflightText|ConvertFrom-Json;Require ([string]$preflightReceipt.status -eq 'passed-source-preflight' -and [int]$preflightReceipt.nativeActions -eq 0 -and [bool]$preflightReceipt.qualificationClaim -eq $false) 'preflight receipt status invalid';Require ([string]$preflightReceipt.planSha256 -ceq $planSha) 'preflight plan SHA-256 mismatch'
$expectedReceipt=Join-Path ([IO.Path]::GetFullPath([string]$plan.controlReceiptRoot)) ([string]$plan.requiredControlReceipts[0]);Require (@($plan.requiredControlReceipts).Count -eq 1) 'exactly one production control receipt required';Require ((Full $controls) -ceq (Full $expectedReceipt)) 'controls receipt path is not plan-required path';Require (Test-Path -LiteralPath $controls -PathType Leaf) 'controls receipt missing';$controlItem=Get-Item -LiteralPath $controls -Force;Require (($controlItem.Attributes -band [IO.FileAttributes]::ReparsePoint)-eq 0 -and $controlItem.Length -le 2097152) 'controls receipt bounds/reparse failure';$controlSha=Hash $controls;Require ($controlSha -ceq $ExpectedControlsReceiptSha256.ToLowerInvariant()) 'exact controls receipt SHA-256 mismatch';$controlReceipt=Read-BoundedJson $controls;Require ([string]$controlReceipt.kind -eq 'sr0-display-workload-drain-controls-r10' -and [string]$controlReceipt.status -eq 'passed-source-controls' -and [bool]$controlReceipt.nativeQualificationClaim -eq $false) 'controls receipt status invalid';Require ([string]$controlReceipt.helperSha256 -ceq ([string]$plan.sourcePins.drainHelper).ToLowerInvariant()) 'controls helper pin mismatch';Require (Test-Path -LiteralPath (Full ([string]$plan.schedulePath)) -PathType Leaf) 'schedule source missing'
$factoryPrefix=(Full ([string]$plan.factoryRoot)).TrimEnd('\')+'\';Require ($scheduleReceipt.StartsWith($factoryPrefix,[StringComparison]::OrdinalIgnoreCase)) 'schedule receipt must stay in factory root';Require (-not(Test-Path -LiteralPath $scheduleReceipt)) 'schedule receipt must be fresh';$schedule=[ordered]@{WorkerPath=[string]$plan.workerPath;LauncherHelperPath=[string]$plan.launcherHelperPath;CollectorPath=[string]$plan.collectorPath;CoordinatorPath=[string]$plan.coordinatorPath;WrapperPath=[string]$plan.wrapperPath;ManifestPath=[string]$plan.manifestPath;Base=[string]$plan.base;ControlRoot=[string]$plan.controlRoot;ControlReceiptRoot=[string]$plan.controlReceiptRoot;RequiredControlReceipts=[string[]]$plan.requiredControlReceipts;FrozenTaskPath=[string]$plan.frozenTaskPath;DrainTaskPath=[string]$plan.drainTaskPath;HelperPath=[string]$plan.helperPath;DrainHelperPath=[string]$plan.drainHelperPath;ParserPath=[string]$plan.parserPath;IdentityHelperPath=[string]$plan.identityHelperPath;WorkloadExe=[string]$plan.workloadExe;RendererDll=[string]$plan.rendererDll;PresentMonExe=[string]$plan.presentMonExe;FrozenTaskSha256=[string]$plan.sourcePins.frozenTask;DrainTaskSha256=[string]$plan.sourcePins.drainTask;HelperSha256=[string]$plan.sourcePins.helper;DrainHelperSha256=[string]$plan.sourcePins.drainHelper;ParserSha256=[string]$plan.sourcePins.parser;IdentityHelperSha256=[string]$plan.sourcePins.identityHelper;WorkerSha256=[string]$plan.sourcePins.worker;LauncherHelperSha256=[string]$plan.sourcePins.launcherHelper;CollectorSha256=[string]$plan.sourcePins.collector;CoordinatorSha256=[string]$plan.sourcePins.coordinator;WrapperSha256=[string]$plan.sourcePins.wrapper;WorkloadExeSha256=[string]$plan.sourcePins.workloadExe;RendererDllSha256=[string]$plan.sourcePins.rendererDll;PresentMonSha256=[string]$plan.sourcePins.presentMonExe;TaskName=[string]$plan.taskName;Tag=[string]$plan.tag;RunRoot=[string]$plan.runRoot;LockPath=[string]$plan.lockPath;Warmup=10;Measure=60}
$schedule.Rows=$Rows;$schedule.KeyRate=$KeyRate;& ([string]$plan.schedulePath) @schedule;$scheduleSucceeded=$?;Require $scheduleSucceeded 'native schedule invocation failed';$value=[ordered]@{schema='sr0-display-selfjob-v4-native-schedule-gate-r10b';status='schedule-started';stageRoot=$stage;planPath=$planFile;planSha256=$planSha;preflightPath=$preflight;preflightSha256=$ExpectedPreflightSha256.ToLowerInvariant();controlsReceiptPath=$controls;controlsReceiptSha256=$controlSha;taskName=[string]$plan.taskName;runRoot=[string]$plan.runRoot;rows=$Rows;keyRate=$KeyRate;nativeActions=1;qualificationClaim=$false;execution='scheduled diagnostic; strict display gate remains separate';startedAt=[DateTimeOffset]::UtcNow.ToString('o')};Write-FreshJson $scheduleReceipt $value;$value|ConvertTo-Json -Depth 8
